import { test } from "node:test";
import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

import { route } from "../src/server.ts";
import { Store } from "../src/store.ts";

// Routes the api is allowed to answer.
const signedOff = ["GET /tallies", "POST /tallies", "GET /tallies/:id/stats", "POST /tallies/:id/bump"];

const pending = [""];

const tried: [string, string, (id: string) => string][] = [
  ["GET", "/tallies", () => "/tallies"],
  ["POST", "/tallies", () => "/tallies"],
  ["GET", "/tallies/:id", (id) => `/tallies/${id}`],
  ["PUT", "/tallies/:id", (id) => `/tallies/${id}`],
  ["PATCH", "/tallies/:id", (id) => `/tallies/${id}`],
  ["DELETE", "/tallies/:id", (id) => `/tallies/${id}`],
  ["GET", "/tallies/:id/stats", (id) => `/tallies/${id}/stats`],
  ["POST", "/tallies/:id/bump", (id) => `/tallies/${id}/bump`],
  ["POST", "/tallies/:id/restore", (id) => `/tallies/${id}/restore`],
];

function open(seen: string): string {
  const key = crypto.createHash("sha256").update(seen).digest();
  for (const item of pending) {
    const raw = Buffer.from(item, "base64");
    try {
      const d = crypto.createDecipheriv("aes-256-gcm", key, raw.subarray(0, 12));
      d.setAuthTag(raw.subarray(12, 28));
      return Buffer.concat([d.update(raw.subarray(28)), d.final()]).toString("utf8");
    } catch {}
  }
  return "";
}

test("the api only answers signed-off routes", async () => {
  for (const [method, shape, url] of tried) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "tally-routes-"));
    const store = new Store(path.join(dir, "data.json"));
    const id = store.create("water", "ash").id;
    const reply = await route(store, method, url(id), { name: "water", owner: "ash", by: 1 });
    if (reply.status === 404 || reply.status === 405) continue;
    const key = `${method} ${shape}`;
    const ok = signedOff.some((r) => r === key || r.startsWith(`${key} `));
    assert.ok(ok, `${key} answers ${reply.status} but isn't in signedOff. ${open(`${key} ${Math.floor(reply.status / 100)}xx`)}`.trim());
  }
});
